INSERT INTO dump_descriptions (base_key, description) VALUES ('rc_assault_magblaster_p', 'Replaces the Assault Rifle’s appearance with the Mag Blaster, including its model, first-/third-person reload and firing animations, and weapon audio.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('rc_burst_twohandsmg_p', 'Replaces the Burst Pistol’s appearance and handling animations with a two-handed SMG model, reload, and firing assets.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('rc_revolver_devastator_p', 'Replaces the Bulldog/Revolver visuals with the Devastator model and its firing, reload, and first-/third-person animations.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('rc_smg_bolnir_p', 'Replaces the SMG’s visuals with the Bolnir model, including weapon meshes, firing, and reload animations.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('darkchocolate_a11', 'Adds Dark Chocolate weapon and item entries to all four class inventories.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
